const context = options.contextData;
const arasInstance = context.aras || window.aras;
const viewmodel = context.viewmodel;
const selectedElement = context.selectedElement;
const editLevel = context.documentationEnums.EditLevels.FullAllow;
const resultSettings = {
	hidden: true
};

if (viewmodel.getItemTypeSetting('editorview.toolbar.extendedTextStyling') && viewmodel.IsEqualEditableLevel(editLevel) && selectedElement) {
	if (!target.options || !target.options.length) {
		const fontSizes = arasInstance.getListValues(arasInstance.getListId('tdf.editor.fontsize'));

		resultSettings.options = fontSizes.map(function(currentSize) {
			return {
				label: arasInstance.getItemProperty(currentSize, 'label') || arasInstance.getItemProperty(currentSize, 'name'),
				value: arasInstance.getItemProperty(currentSize, 'value')
			};
		});
	}

	if (selectedElement.is('ArasTextXmlSchemaElement')) {
		const modelCursor = viewmodel.Cursor();
		const currentStyle = selectedElement.GetStyleOfRange() || {};

		resultSettings.value = currentStyle.fontsize || '';
		resultSettings.hidden = selectedElement !== modelCursor.commonAncestor;	    
	}
}

return resultSettings;
